def forwards(apps, schema_editor):
    """
    Payment methods were codes from a closed list; the field now holds the
    words, so a method typed by hand and one picked from the list look alike.
    And every quote's single reason becomes the first of its reasons.
    """
    for name in ("Quote", "PurchaseOrder"):
        model = apps.get_model("commercial", name)
        for code, label in LABELS.items():
            model.objects.filter(payment_method=code).update(payment_method=label)
    Quote = apps.get_model("commercial", "Quote")
    for quote in Quote.objects.exclude(reason=None).iterator():
        quote.reasons.add(quote.reason_id)


